GREY = RGBColor(0x6b, 0x72, 0x80)
INK = RGBColor(0x11, 0x18, 0x27)


def hexc(h): return RGBColor.from_string(h)


def shade(cell, hx):
    tcPr = cell._tc.get_or_add_tcPr(); sh = OxmlElement('w:shd')
    sh.set(qn('w:val'), 'clear'); sh.set(qn('w:color'), 'auto'); sh.set(qn('w:fill'), hx); tcPr.append(sh)


def borders(table, color='E5E7EB'):
    tbl = table._tbl; tblPr = tbl.tblPr; b = OxmlElement('w:tblBorders')
    for e in ('top', 'bottom', 'insideH'):
        x = OxmlElement(f'w:{e}'); x.set(qn('w:val'), 'single'); x.set(qn('w:sz'), '4'); x.set(qn('w:color'), color); b.append(x)
    tblPr.append(b)


def newdoc(accent='2563EB', kicker='', title='', sub=''):
    d = Document(); s = d.sections[0]
    s.page_width = Cm(21); s.page_height = Cm(29.7); s.left_margin = s.right_margin = Cm(2.3); s.top_margin = Cm(2.0); s.bottom_margin = Cm(1.8)
    st = d.styles['Normal']; st.font.name = 'Calibri'; st.font.size = Pt(10.5); st.paragraph_format.space_after = Pt(5)
    st.element.rPr.rFonts.set(qn('w:eastAsia'), 'Calibri')
    if kicker:
        p = d.add_paragraph(); r = p.add_run(kicker.upper()); r.font.size = Pt(8.5); r.bold = True; r.font.color.rgb = hexc(accent)
        p.paragraph_format.space_after = Pt(2)
    p = d.add_paragraph(); r = p.add_run(title); r.bold = True; r.font.size = Pt(24); r.font.color.rgb = INK
    p.paragraph_format.space_after = Pt(2)
    if sub:
        p = d.add_paragraph(); r = p.add_run(sub); r.font.size = Pt(11); r.font.color.rgb = GREY
    d.add_paragraph().paragraph_format.space_after = Pt(4)
    return d


def h(d, text, accent='2563EB', size=12):
    p = d.add_paragraph(); p.paragraph_format.space_before = Pt(8); p.paragraph_format.space_after = Pt(3)
    r = p.add_run(text); r.bold = True; r.font.size = Pt(size); r.font.color.rgb = INK
    return p


def para(d, text, color=None, bold=False, size=None, after=None):
    p = d.add_paragraph(); r = p.add_run(text); r.bold = bold
    if color: r.font.color.rgb = color
    if size: r.font.size = Pt(size)
    if after is not None: p.paragraph_format.space_after = Pt(after)
    return p


def table(d, rows, widths, accent='2563EB', right=(), hdr=True):
    t = d.add_table(rows=len(rows), cols=len(rows[0])); t.alignment = WD_TABLE_ALIGNMENT.LEFT; borders(t)
    for i, row in enumerate(rows):
        for j, v in enumerate(row):
            c = t.cell(i, j); c.width = Cm(widths[j]); c.text = ''
            p = c.paragraphs[0]; p.paragraph_format.space_after = Pt(2); p.paragraph_format.space_before = Pt(2)
            r = p.add_run(str(v)); r.font.size = Pt(9.5)
            if j in right: p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
            if i == 0 and hdr:
                r.bold = True; r.font.color.rgb = RGBColor(255, 255, 255); shade(c, accent)
    return t


def bullets(d, items):
    for t in items:
        p = d.add_paragraph(style='List Bullet'); p.paragraph_format.space_after = Pt(2)
        if isinstance(t, tuple):
            r = p.add_run(t[0]); r.bold = True; p.add_run(t[1])
        else:
            p.add_run(t)


