    h(d, 'Summary')
    para(d, 'Supplier B has the best total cost for ten desks once delivery and the warranty are included. Supplier A is fastest. Supplier C is cheapest per unit but ships from abroad and has the shortest warranty.')
    h(d, 'Comparison')
    table(d, [('', 'Supplier A', 'Supplier B', 'Supplier C'), ('Unit price', 'GH₵ 2,950', 'GH₵ 2,700', 'GH₵ 2,400'), ('Delivery', '3 days', '10 days', '5 weeks'),
              ('Warranty', '3 years', '5 years', '1 year'), ('Frame', 'Dual motor', 'Dual motor', 'Single motor'), ('Total for 10', 'GH₵ 29,900', 'GH₵ 27,400', 'GH₵ 26,800')], [3.4, 4.2, 4.2, 4.2], '0EA5E9')
    h(d, 'What to check before ordering')
    bullets(d, ['Whether Supplier B holds stock locally or ships to order.', 'Import duty on Supplier C, which is not in the price shown.', 'Load rating: the studio monitors weigh more than the standard 70 kg.'])
    h(d, 'Sources')
    para(d, '1. Supplier A price list, accessed this week\n2. Supplier B product page and warranty terms\n3. Supplier C quote request', GREY, size=9)
    d.save(f'{OUT}/research.docx')


