def code():
    d = newdoc('16A34A', 'Code review', 'Pull request #42: login fix', 'Three findings, one blocking.')
    h(d, 'Blocking')
    para(d, 'auth/session.ts, line 58', bold=True, after=1)
    para(d, 'The refresh token is compared with ==. Use a constant-time comparison so response time does not leak the token.')
    h(d, 'Should fix')
    para(d, 'auth/session.ts, line 91', bold=True, after=1)
    para(d, 'The error path returns before the session is cleared, so a failed refresh leaves the old cookie in place.')
    h(d, 'Suggestion')
    para(d, 'tests/session.test.ts', bold=True, after=1)
    para(d, 'Add a case for an expired refresh token. The fix is covered, the failure path is not.')
    d.add_paragraph()
    table(d, [('Check', 'Result'), ('Unit tests', 'Passing'), ('Type check', 'Passing'), ('New tests added', 'None')], [8, 8], '16A34A')
    d.save(f'{OUT}/code.docx')


