# ---------------------------------------------------------------- XLSX
def style_sheet(ws, widths, hdr_fill='111827'):
    for i, w in enumerate(widths): ws.column_dimensions[chr(65 + i)].width = w
    for c in ws[1]:
        c.font = Font(bold=True, color='FFFFFF', name='Calibri'); c.fill = PatternFill('solid', fgColor=hdr_fill); c.alignment = Alignment(horizontal='left', vertical='center')
    ws.row_dimensions[1].height = 22
    thin = Side(style='thin', color='E5E7EB')
    for row in ws.iter_rows(min_row=2):
        for c in row: c.border = Border(bottom=thin); c.font = Font(name='Calibri', size=11)
    ws.sheet_view.showGridLines = False


