# ---------------------------------------------------------------- PPTX
def deck():
    p = Presentation(); p.slide_width = Inches(13.333); p.slide_height = Inches(7.5)
    s = p.slides.add_slide(p.slide_layouts[6])
    bg = s.background.fill; bg.solid(); bg.fore_color.rgb = PRGB(0x0B, 0x10, 0x20)
    def tb(x, y, w, hh, text, size, color, bold=False):
        t = s.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(hh)); tf = t.text_frame; tf.word_wrap = True
        r = tf.paragraphs[0].add_run(); r.text = text; r.font.size = PPt(size); r.font.bold = bold; r.font.color.rgb = PRGB(*color); r.font.name = 'Calibri'; return t
    tb(0.9, 0.8, 8, 0.4, 'QUARTER IN REVIEW', 14, (0x60, 0xA5, 0xFA), True)
    tb(0.9, 1.3, 11, 1.8, 'Sales grew every month since May', 54, (255, 255, 255), True)
    for i, (n, l) in enumerate([('GH₵ 27k', 'October sales'), ('+125%', 'Since May'), ('4.2 days', 'Average delivery')]):
        x = 0.9 + i * 4.0
        box = s.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, Inches(x), Inches(4.2), Inches(3.6), Inches(2.2)); box.fill.solid(); box.fill.fore_color.rgb = PRGB(0x13, 0x1B, 0x33)
        box.line.color.rgb = PRGB(0x2A, 0x3A, 0x6B); box.adjustments[0] = 0.08
        tb(x + .35, 4.55, 3.0, 1.0, n, 40, (255, 255, 255), True); tb(x + .35, 5.5, 3.0, .6, l, 16, (0x9C, 0xA3, 0xAF))
    p.save(f'{OUT}/deck.pptx')


